interactions.sample_code:
while (!isEmpty(L) && !isEmpty(R)) {
    if (peek(L) <= peek(R)) {
        take(L);
    } else {
        take(R);
    }
}
while (!isEmpty(L)) take(L);
while (!isEmpty(R)) take(R);

